package com.lianxibu.site.domain.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;
class BacklogHistoryTelemetryTest{
 static final Instant START=Instant.parse("2026-01-01T16:00:00Z"),END=START.plusSeconds(3600);
 Entry entry(List<Span> spans){return new Entry("fictional-root",3,"queued",START,END,spans);}
 @Test void actualEmptySnapshotAndMissingHistoricalProofAreDifferent(){assertTrue(new Evidence(END,List.of()).entries().isEmpty());assertNull(new Evidence(END,List.of(entry(null))).entries().getFirst().spans());assertEquals(3600,Duration.between(entry(null).createdAt(),entry(null).readAt()).toSeconds());assertEquals("BacklogHistoryEvidence[redacted]",new Evidence(END,List.of()).toString());}
 @Test void completeDurableSpansRetainReadyAndPauseSeparatelyAndAreImmutable(){var mutable=new ArrayList<Span>();mutable.add(new Span(START,START.plusSeconds(1200),false,false));mutable.add(new Span(START.plusSeconds(1200),START.plusSeconds(2400),true,true));mutable.add(new Span(START.plusSeconds(2400),END,true,false));var row=entry(mutable);mutable.clear();assertEquals(3,row.spans().size());assertThrows(UnsupportedOperationException.class,()->row.spans().clear());assertEquals("BacklogHistoryEntry[redacted]",row.toString());assertEquals("BacklogHistorySpan[redacted]",row.spans().getFirst().toString());}
 @Test void gapOverlapIncompleteCoverageDuplicateRootAndOverflowAreRejected(){for(var spans:List.of(List.<Span>of(),List.of(new Span(START.plusSeconds(1),END,true,false)),List.of(new Span(START,END.minusSeconds(1),true,false)),List.of(new Span(START,START.plusSeconds(2000),true,false),new Span(START.plusSeconds(1999),END,false,false))))assertThrows(IllegalArgumentException.class,()->entry(spans));var row=entry(null);assertThrows(IllegalArgumentException.class,()->new Evidence(END,List.of(row,row)));assertThrows(IllegalArgumentException.class,()->new Evidence(END,java.util.stream.IntStream.range(0,4097).mapToObj(i->new Entry("fictional-"+i,1,"queued",START,END,null)).toList()));assertThrows(IllegalArgumentException.class,()->new Evidence(END.plusSeconds(1),List.of(row)));}
 @Test void terminalWrongPriorityBadPrecisionFutureBirthAndOldIntervalCannotBecomeFacts(){for(String state:List.of("succeeded","cancelled","discarded","superseded","fictional"))assertThrows(IllegalArgumentException.class,()->new Entry("fictional-root",1,state,START,END,null));for(int priority:new int[]{0,15})assertThrows(IllegalArgumentException.class,()->new Entry("fictional-root",priority,"queued",START,END,null));assertThrows(IllegalArgumentException.class,()->new Evidence(END.plusNanos(1),List.of()));assertThrows(IllegalArgumentException.class,()->new Entry("fictional-root",1,"queued",END,START,null));assertThrows(IllegalArgumentException.class,()->new Span(START,START.plus(Duration.ofDays(3661)),true,false));assertThrows(IllegalArgumentException.class,()->new Entry("fictional-root",1,"queued",START,START.plus(Duration.ofDays(3661)),null));assertThrows(IllegalArgumentException.class,()->new Span(END,START,true,false));}
 @Test void unknownIntervalRemainsExplicitAndNativeMutationEpochTimesAreBounded(){var span=new Span(START,END,null,null);assertNull(span.ready());assertNull(span.globallyPaused());var row=entry(List.of(span));var mutation=new Mutation("00000000-0000-4000-8000-000000000001",START,END,0);var facts=new Evidence(END,List.of(row),mutation);assertSame(mutation,facts.mutation());assertEquals("BacklogMutationWitness[redacted]",mutation.toString());assertNull(new Evidence(END,List.of()).mutation());}
 @Test void invalidMutationIdentitySequenceAndFutureTimeCannotQualifyHistory(){String epoch="00000000-0000-4000-8000-000000000001";for(String bad:List.of("fictional",epoch.toUpperCase()+"x"))assertThrows(IllegalArgumentException.class,()->new Mutation(bad,START,END,1));for(long count:new long[]{-1,9007199254740992L})assertThrows(IllegalArgumentException.class,()->new Mutation(epoch,START,END,count));assertThrows(IllegalArgumentException.class,()->new Mutation(epoch,END,START,1));assertThrows(IllegalArgumentException.class,()->new Mutation(epoch,START,END.plusNanos(1),1));assertThrows(IllegalArgumentException.class,()->new Evidence(END,List.of(),new Mutation(epoch,START,END.plusSeconds(1),1)));}
}
